const rss_urls = [
  'https://feeds.bbci.co.uk/news/technology/rss.xml',
  'https://www.nasa.gov/rss/dyn/breaking_news.rss'
];
const keywords = ['openai', 'anthropic', 'n8n', 'postgres', 'embeddings'];
const config = {
  dedupe_ttl_days: 7,
  cache_ttl_minutes: 30,
  min_score: 10,
  max_items_total: 25,
  enable_llm_summary: true,
  ZAI_API_KEY: $env.ZAI_API_KEY || '',
  ZAI_BASE_URL: $env.ZAI_BASE_URL || 'https://api.z.ai/api/paas/v4',
  ZAI_MODEL: $env.ZAI_MODEL || 'glm-5'
};
return [{ json: { rss_urls, keywords, config } }];

const items = $input.all();
const config = $('Init').first().json.config;
const out = [];

for (const item of items) {
  const feedUrl = item.json.rss_url;
  const feedData = item.json;
  const entries = feedData.items || [];

  for (const entry of entries) {
    out.push({
      json: {
        source: 'rss',
        keyword: null,
        title: entry.title || 'Untitled',
        url: entry.link || entry.guid || '',
        published_at: entry.pubDate || entry.isoDate || null,
        raw_score: 15,
        score: 15,
        summary_raw: entry.contentSnippet || entry.summary || null,
        summary: null,
        meta: {
          author: entry.creator || null,
          venue: feedUrl ? new URL(feedUrl).hostname : 'RSS Feed',
          cached: false,
          api_calls: 0,
          failed_calls: 0
        }
      }
    });
  }
}
return out.length > 0 ? out : [{ json: { __empty: true, __stream: 'rss' } }];

const init = $('Init').first().json;
return [{
  json: {
    keyword: $json.keyword,
    config: init.config
  }
}];

const allItems = $input.all();
const initData = $('Init').first().json;
const config = initData.config;
const keywords = initData.keywords;
const staticData = $getWorkflowStaticData('global');

if (!staticData.seen) staticData.seen = {};
const now = Date.now();
const ttlMs = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;

// Prune TTL
for (const key of Object.keys(staticData.seen)) {
  if (now - staticData.seen[key] > ttlMs) delete staticData.seen[key];
}

const validItems = allItems.map(i => i.json).filter(i => !i.__empty);
const candidatesTotal = validItems.length;
const stats = { cached_hits: 0, api_calls: 0, failed_calls: 0, by_source: {} };
const finalItems = [];

for (const item of validItems) {
  stats.by_source[item.source] = (stats.by_source[item.source] || 0) + 1;
  if (item.meta?.cached) stats.cached_hits++;
  if (item.meta?.api_calls) stats.api_calls += item.meta.api_calls;
  if (item.meta?.failed_calls) stats.failed_calls += item.meta.failed_calls;

  const id = item.url || item.title;
  if (id && !staticData.seen[id]) {
    staticData.seen[id] = now;
    if (item.score >= config.min_score) finalItems.push(item);
  }
}

finalItems.sort((a, b) => b.score - a.score);
const sliced = finalItems.slice(0, config.max_items_total);

return [{
  json: {
    config,
    stats: { candidates_total: candidatesTotal, new_items: finalItems.length, ...stats },
    items: sliced,
    keywords,
    run_id: $execution.id,
    generated_at: new Date().toISOString()
  }
}];

const data = $json;
const top10 = data.items.slice(0, 10);
const promptContext = top10.map(i => `URL: ${i.url}\nTitle: ${i.title}`).join('\n\n');

return [{
  json: {
    config: data.config,
    items: data.items,
    stats: data.stats,
    keywords: data.keywords,
    run_id: data.run_id,
    generated_at: data.generated_at,
    llm_payload: {
      model: data.config.ZAI_MODEL,
      messages: [{
        role: 'user',
        content: `Generate a 1-sentence summary for each item. Return JSON: {"summaries":[{"url":"...","summary":"..."}]}\n\n${promptContext}`
      }],
      response_format: { type: 'json_object' }
    }
  }
}];

const prev = $('Prepare LLM').item.json;
let items = prev.items;
const response = $json;

if (response?.choices?.[0]?.message?.content) {
  try {
    const parsed = JSON.parse(response.choices[0].message.content);
    if (parsed.summaries && Array.isArray(parsed.summaries)) {
      const map = {};
      parsed.summaries.forEach(s => map[s.url] = s.summary);
      items = items.map(i => ({ ...i, summary: map[i.url] || i.summary_raw || i.title }));
    }
  } catch (e) {
    items = items.map(i => ({ ...i, summary: i.summary_raw || i.title }));
  }
} else {
  items = items.map(i => ({ ...i, summary: i.summary_raw || i.title }));
}

return [{ json: { ...prev, items } }];

const data = $json;
const items = data.items.map(i => ({ ...i, summary: i.summary_raw || i.title }));
return [{ json: { ...data, items } }];

const data = $json;
if (!Array.isArray(data.items)) throw new Error('QA: items not array');
data.items.forEach(i => {
  if (!i.url) throw new Error('QA: item missing url');
  if (typeof i.score !== 'number') throw new Error('QA: score not number');
});
const str = JSON.stringify(data);
if (str.includes('{{')) throw new Error('QA: mustache detected');
return [{ json: data }];

const data = $json;
const digest = data.items.map(i => `* [${i.score}] ${i.title}\n  ${i.url}\n  ${i.summary || 'No summary'}`).join('\n\n');
return [{
  json: {
    run_id: data.run_id,
    generated_at: data.generated_at,
    keywords: data.keywords,
    stats: data.stats,
    items: data.items,
    digest_markdown: digest
  }
}];
